css:
body :where([data-bz-node="ld"]) .bz-block{padding:0}
body :where([data-bz-node="ld"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="ld"]>.bz-container{padding-inline:0}

body [data-bz-node="ld"]{background:#fff;padding:90px 0 60px}
body [data-bz-node="ld"]>.bz-container{max-width:var(--container)}
body [data-bz-node="ld-row"]{display:grid;grid-template-columns:1fr 1fr;gap:0 64px;align-items:center}
body [data-bz-node="ld-media"],body [data-bz-node="ld-copy"]{grid-column:auto}
body [data-bz-node="ld-media"] figure{margin:0}
body [data-bz-node="ld-media"] img{width:100%;height:auto;border-radius:0}
body [data-bz-node="ld-h"] h2{font:700 36px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;max-width:520px}
body [data-bz-node="ld-text"] .bz-text{max-width:540px;margin-top:22px}
body [data-bz-node="ld-text"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0 0 14px}
body [data-bz-node="ld-text"] p:last-child{margin:0}
@media (max-width:1100px){body [data-bz-node="ld"]{padding:64px 24px 40px}body [data-bz-node="ld-row"]{grid-template-columns:1fr;gap:32px}body [data-bz-node="ld-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="ld"]{padding:48px 20px 32px}body [data-bz-node="ld-h"] h2{font-size:26px}}
